import * as T from './vendor/three.module.js';
import {createModel} from './flight-models.js';
const $=id=>document.getElementById(id),page=document.body.dataset.page;
const records={
nasa:[
{title:'Hubble Space Telescope',tag:'01 / A WINDOW ON THE UNIVERSE',model:'hubble',desc:'Launched in 1990, Hubble observes from above Earth’s atmosphere. Its ultraviolet, visible and near-infrared observations have helped scientists study galaxies, stars and planets.',stats:[['LAUNCH','1990'],['LOCATION','Earth orbit'],['ROLE','Space observatory']],facts:[['A telescope astronauts could visit','Space Shuttle crews serviced Hubble, replacing equipment and installing improved instruments.'],['Sharper views above the air','Observing above most of the atmosphere avoids the blurring that affects ground-based images.'],['Different light, different clues','Hubble’s views complement Webb’s infrared observations rather than duplicating them.']],source:'https://science.nasa.gov/mission/hubble/overview/about-hubble/'},
{title:'James Webb Space Telescope',tag:'02 / THE INFRARED UNIVERSE',model:'webb',desc:'Webb studies infrared light to investigate early galaxies, star formation and planetary atmospheres. It is an international mission led by NASA with ESA and the Canadian Space Agency.',stats:[['LAUNCH','2021'],['MIRROR SEGMENTS','18'],['SPECIALTY','Infrared light']],facts:[['A mirror that unfolded','Its primary mirror is assembled from 18 hexagonal, gold-coated segments.'],['Shade for sensitive instruments','A five-layer sunshield helps separate the telescope’s cold side from the Sun’s heat.'],['Light takes time to travel','Distant galaxies are seen as they were long ago, allowing astronomers to study earlier cosmic history.']],source:'https://science.nasa.gov/mission/webb/fact-sheet/'},
{title:'Perseverance',tag:'03 / A ROBOTIC GEOLOGIST',model:'rover',desc:'Perseverance landed in Jezero Crater on Mars on February 18, 2021. It investigates ancient environments, seeks possible signs of past microbial life, and collects samples for potential future study on Earth.',stats:[['LANDING','2021'],['DESTINATION','Jezero Crater'],['TYPE','Mars rover']],facts:[['An ancient landscape','Jezero preserves evidence of a former lake and river delta.'],['Samples with a story','Rock and regolith samples can preserve clues about the planet’s geological history.'],['Questions, not assumptions','Searching for signs of life does not mean life has been confirmed. Evidence needs careful scientific analysis.']],source:'https://science.nasa.gov/mission/mars-2020-perseverance/'},
{title:'Apollo 11',tag:'04 / HUMANS ON ANOTHER WORLD',model:'apollo',desc:'Apollo 11 carried Neil Armstrong, Buzz Aldrin and Michael Collins to the Moon in July 1969. Armstrong and Aldrin explored the surface while Collins remained in lunar orbit.',stats:[['LUNAR LANDING','1969'],['CREW','3 astronauts'],['LANDER','Eagle']],facts:[['Two spacecraft, different roles','A lunar module descended to the surface; the command and service modules supported the journey and lunar-orbit operations.'],['Science came home','The crew returned lunar material for researchers on Earth.'],['A team far beyond the capsule','Engineers, flight controllers, scientists and many others made the mission possible.']],source:'https://www.nasa.gov/history/apollo-11-mission-overview/'}],
spacex:[
{title:'Falcon 9',tag:'01 / REUSABLE FIRST STAGE',model:'falcon9',desc:'SpaceX’s two-stage launch vehicle carries satellites and Dragon spacecraft. Its first stage can return for recovery and reuse; the upper stage continues the mission toward orbit.',stats:[['ARCHITECTURE','Two stages'],['BOOSTER ENGINES','9 Merlin'],['RECOVERY','First stage']],facts:[['Two stages, different jobs','The booster supplies the early push. The upper stage continues accelerating the payload after separation.'],['A controlled return','On recovery missions, the booster uses guidance, engine burns and landing legs to return to land or a droneship.'],['Reuse has limits','Falcon 9 is partially reusable. Its second stage is not recovered for another flight.']],source:'https://www.spacex.com/vehicles/falcon-9'},
{title:'Falcon Heavy',tag:'02 / THREE-CORE LAUNCH VEHICLE',model:'falconheavy',desc:'Falcon Heavy combines a center core with two side boosters. Its three first-stage cores provide extra thrust for demanding payloads and destinations.',stats:[['FIRST-STAGE CORES','3'],['BOOSTER ENGINES','27 Merlin'],['ROLE','Heavy payloads']],facts:[['A family resemblance','Its architecture builds on Falcon 9 technology.'],['Three cores working together','Each first-stage core has nine Merlin engines, for 27 at liftoff.'],['Recovery depends on the mission','Payload and trajectory requirements affect which boosters can be recovered.']],source:'https://www.spacex.com/vehicles/falcon-heavy'},
{title:'Dragon',tag:'03 / ORBITAL SPACECRAFT',model:'dragon',desc:'Dragon is a spacecraft, not the rocket beneath it. Crew and cargo versions travel to the International Space Station, and the capsule returns through Earth’s atmosphere.',stats:[['LAUNCH VEHICLE','Falcon 9'],['VERSIONS','Crew / cargo'],['CREW DEBUT','Demo-2 · 2020']],facts:[['A capsule and a trunk','The pressurized capsule carries people or cargo. The unpressurized trunk supports the spacecraft during flight.'],['A protected return','A heat shield protects the capsule during reentry, then parachutes slow it for splashdown.'],['A milestone for crews','Demo-2 launched Bob Behnken and Doug Hurley on May 30, 2020, demonstrating the crew transportation system.']],source:'https://www.nasa.gov/commercial-crew-program-press-kit/'},
{title:'Starship',tag:'04 / FULL-REUSE DESIGN GOAL',model:'starship',desc:'The Starship system pairs a large spacecraft and upper stage with the Super Heavy booster. SpaceX’s design goal is to recover and reuse both stages for missions to Earth orbit and beyond.',stats:[['BOOSTER','Super Heavy'],['UPPER STAGE','Starship'],['DESIGN GOAL','Full reuse']],facts:[['One name, two uses','“Starship” can refer to the upper vehicle or to the complete launch system.'],['A different approach','The system is designed around reusing both stages, unlike Falcon 9’s first-stage recovery.'],['Follow the evidence','Vehicle configurations, tests and mission plans evolve. Check the official program page for current details; this is an architectural overview.']],source:'https://www.spacex.com/vehicles/starship'}],
spaceships:[
{title:'Apollo spacecraft',tag:'01 / LUNAR EXPLORATION',model:'apollo',desc:'A small home for a very big journey. Apollo’s command and service modules carried astronauts between Earth and lunar orbit; a separate lunar module made the descent to the Moon.',stats:[['MISSION','Apollo 11'],['CREW','3 astronauts'],['LAUNCH YEAR','1969']],facts:[['Two vehicles, one mission','The lunar module landed with two astronauts while a third remained in lunar orbit in the command module.'],['The ride home','The command module was the part that returned the crew through Earth’s atmosphere.'],['Science came back, too','Apollo 11’s crew returned lunar samples for study on Earth.']],source:'https://www.nasa.gov/history/apollo-11-mission-overview/'},
{title:'Space Shuttle',tag:'02 / REUSABLE ORBITER',model:'shuttle',desc:'Part rocket-launched spacecraft, part glider. The Space Shuttle carried crews and cargo into Earth orbit, deployed satellites, and helped assemble the International Space Station.',stats:[['PROGRAM','1981–2011'],['MISSIONS','135'],['LANDING','Runway']],facts:[['A gliding return','After reentry, the orbiter landed on a runway without powered jet engines.'],['A workshop in orbit','Shuttle crews repaired and upgraded the Hubble Space Telescope during servicing missions.'],['Building a space station','The orbiters delivered major station components and helped crews assemble them in orbit.']],source:'https://www.nasa.gov/space-shuttle/'},
{title:'Voyager 1',tag:'03 / ROBOTIC PATHFINDER',model:'voyager',desc:'No cabin. No crew. Just an extraordinary robotic explorer. Launched in 1977 to visit Jupiter and Saturn, Voyager 1 crossed the heliopause into interstellar space in 2012.',stats:[['LAUNCH YEAR','1977'],['CREW','Robotic'],['MILESTONE','Interstellar space']],facts:[['A message from Earth','Its Golden Record carries sounds and images chosen to represent life and culture on our planet.'],['A very different power source','Radioisotope generators supply electricity far from the Sun, where sunlight is weak.'],['Crossing a boundary','The heliopause is the boundary between the solar wind’s region of influence and the interstellar medium.']],source:'https://science.nasa.gov/mission/voyager/voyager-1/'}],
spacesuits:[
{title:'A spacecraft you wear.',tag:'01 / HELMET & VISOR',model:'suit',part:'helmet',desc:'The helmet maintains a pressurized space around the head. Protective visors and sun shades help manage glare and exposure while preserving an astronaut’s view.',stats:[['ROLE','Protection'],['ENVIRONMENT','Vacuum'],['MODEL','EVA concept']],facts:[['A view with protection','Visors help protect the eyes from intense sunlight.'],['Communication matters','Microphones and earphones let the crew stay in touch.'],['Designed as a system','The helmet works with the suit’s pressure garment and life support.']]},
{title:'Your own life support.',tag:'02 / LIFE-SUPPORT BACKPACK',model:'suit',part:'backpack',desc:'A spacewalking suit carries a portable life-support system. It supplies oxygen, removes carbon dioxide, and helps keep the astronaut at a workable temperature.',stats:[['SUPPLY','Oxygen'],['REMOVAL','Carbon dioxide'],['CONTROL','Temperature']],facts:[['More than an oxygen tank','Breathing requires circulating gas and removing the carbon dioxide an astronaut exhales.'],['A cool layer underneath','Water circulates through tubes in a special garment worn under the suit.'],['A personal environment','Life-support equipment lets a spacewalker work outside a pressurized spacecraft.']]},
{title:'Pressure. Protection. Mobility.',tag:'03 / PRESSURE GARMENT',model:'suit',part:'pressure',desc:'The suit’s layers maintain pressure, insulate the astronaut, and provide protection. Joints and bearings help the wearer move against the resistance of a pressurized suit.',stats:[['LAYER','Pressure garment'],['CHALLENGE','Mobility'],['DESIGN','Multiple layers']],facts:[['Space is not just cold','Sunlight and shadow create very different thermal conditions. A suit must manage heat as well as cold.'],['Movement takes engineering','A pressurized suit resists bending, so carefully designed joints make work possible.'],['Different suits, different jobs','Launch-and-entry suits and spacewalk suits are designed for different environments.']]},
{title:'Small movements. Big jobs.',tag:'04 / GLOVES & ARMS',model:'suit',part:'gloves',desc:'Astronauts need to grip handrails and use tools while staying protected. Gloves balance pressure, insulation and flexibility, making dexterity an important engineering challenge.',stats:[['TASK','Use tools'],['NEED','Dexterity'],['PRIORITY','Protection']],facts:[['Hands do the hard work','Turning a fastener or gripping a tool becomes more difficult inside a pressurized glove.'],['Practice before flight','Training helps astronauts rehearse the motions needed for tasks outside a spacecraft.'],['Fit matters','Well-fitted suit components support movement and reduce the effort needed to work.']]}],
astronauts:[
{title:'Neil Armstrong',tag:'01 / APOLLO 11 COMMANDER',model:'suit',desc:'A test pilot and engineer who became the first person to walk on the Moon during Apollo 11 in July 1969. His work combined careful preparation, piloting and teamwork.',stats:[['MISSION','Apollo 11'],['MILESTONE','First lunar steps'],['YEAR','1969']],facts:[['An earlier journey','Armstrong flew on Gemini 8 before commanding Apollo 11.'],['A team of three','Buzz Aldrin joined him on the lunar surface while Michael Collins remained in lunar orbit.'],['Engineering and exploration','His career included research flying before the astronaut program.']],source:'https://www.nasa.gov/people/neil-a-armstrong/'},
{title:'Sally Ride',tag:'02 / STS-7 MISSION SPECIALIST',model:'suit',desc:'A physicist who became the first American woman in space on June 18, 1983. Aboard Challenger, she worked as part of the STS-7 crew on satellite operations.',stats:[['MISSION','STS-7'],['SPACECRAFT','Challenger'],['YEAR','1983']],facts:[['Science in the cockpit','Ride brought a physics background to her astronaut work.'],['A robotic helping hand','She helped develop and operate the Shuttle’s robotic arm.'],['More than one flight','She returned to space on STS-41G in 1984.']],source:'https://www.nasa.gov/former-astronaut-sally-ride/'},
{title:'Mae Jemison',tag:'03 / STS-47 MISSION SPECIALIST',model:'suit',desc:'A physician and engineer who became the first African American woman in space in September 1992. On Endeavour’s STS-47 mission, she helped carry out scientific research.',stats:[['MISSION','STS-47'],['SPACECRAFT','Endeavour'],['YEAR','1992']],facts:[['A multidisciplinary explorer','Jemison trained in engineering and medicine before her spaceflight.'],['A laboratory in orbit','The Spacelab-J mission included experiments in life sciences and materials science.'],['International teamwork','STS-47 was a joint mission with Japan’s space agency.']],source:'https://www.nasa.gov/former-astronaut-mae-c-jemison/'}]};
let renderer,scene,camera,model,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,zoom=6.5;let selected=0;
function select(i){selected=i;const d=records[page][i];$('subject-title').textContent=d.title;$('subject-tag').textContent=d.tag;$('subject-description').textContent=d.desc;$('subject-stats').innerHTML=d.stats.map(([k,v])=>`<div><small>${k}</small><strong>${v}</strong></div>`).join('');$('subject-facts').innerHTML=d.facts.map(([h,p],i)=>`<article><span>0${i+1} / FIELD NOTE</span><h3>${h}</h3><p>${p}</p></article>`).join('');$('subject-source').href=d.source||'https://www.nasa.gov/centers-and-facilities/johnson/spacewalk-spacesuit-basics/';document.querySelectorAll('.subject-option').forEach((b,n)=>{b.classList.toggle('selected',i===n);b.setAttribute('aria-pressed',String(i===n))});if(scene){if(model){scene.remove(model);model.traverse(o=>{o.geometry?.dispose();o.material?.dispose()})}const built=createModel(d.model);model=built.root;if(d.part)for(const m of built.parts[d.part]||[]){m.material.emissive.set('#759454');m.material.emissiveIntensity=.28}scene.add(model)} }
records[page].forEach((d,i)=>{const b=document.createElement('button');b.className='subject-option';b.innerHTML=`<span>0${i+1}</span>${page==='spacesuits'?['Helmet & visor','Life support','Pressure layers','Gloves & arms'][i]:d.title}<b>↗</b>`;b.onclick=()=>select(i);$('subject-options').append(b)});
try{const el=$('flight-viewport');renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));el.append(renderer.domElement);scene=new T.Scene();camera=new T.PerspectiveCamera(36,1,.1,100);camera.position.set(0,0,zoom);scene.add(new T.HemisphereLight(0xcbdfff,0x172118,2.3));const key=new T.DirectionalLight(0xfff3db,3.4);key.position.set(-3,4,5);scene.add(key);const rim=new T.DirectionalLight(0x9bbaff,3);rim.position.set(4,0,-3);scene.add(rim);const positions=[];for(let i=0;i<450;i++)positions.push((Math.random()-.5)*20,(Math.random()-.5)*15,-4-Math.random()*6);const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));scene.add(new T.Points(g,new T.PointsMaterial({color:0x7e97ac,size:.016})));new ResizeObserver(()=>{renderer.setSize(el.clientWidth,el.clientHeight);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix()}).observe(el);let drag=false,x=0,y=0;el.addEventListener('pointerdown',e=>{drag=true;x=e.clientX;y=e.clientY;el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!drag||!model)return;model.rotation.y+=(e.clientX-x)*.01;model.rotation.x+=(e.clientY-y)*.007;x=e.clientX;y=e.clientY});el.addEventListener('pointerup',()=>drag=false);el.addEventListener('pointercancel',()=>drag=false);el.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(4.5,Math.min(9,zoom+e.deltaY*.005))},{passive:false});let previous=0;renderer.setAnimationLoop(t=>{const dt=Math.min((t-previous)/1000,.05);previous=t;if(model&&!paused&&!drag)model.rotation.y+=dt*.12;camera.position.z+=(zoom-camera.position.z)*.1;renderer.render(scene,camera)});$('model-fallback').hidden=true}catch(e){$('model-fallback').textContent='3D is unavailable in this browser. Explore the facts and guides below.';$('model-controls').hidden=true}
$('rotate').onclick=()=>{paused=!paused;updatePause()};function updatePause(){$('rotate').textContent=paused?'▷ Resume':'Ⅱ Pause';$('rotate').setAttribute('aria-pressed',String(paused))}updatePause();$('zoom-in').onclick=()=>zoom=Math.max(4.5,zoom-.5);$('zoom-out').onclick=()=>zoom=Math.min(9,zoom+.5);$('reset-model').onclick=()=>{zoom=6.5;select(selected)};select(0);
